/**
 * collapseTraceGraph — hide a caller-chosen set of nodes from a `TraceGraph`,
 * honestly: the nodes disappear, the edges through them are re-connected, and
 * the caller gets the list of what was hidden so the UI can SAY so.
 *
 * The mechanism is deliberately NEUTRAL: this library has no idea what makes a
 * node worth hiding — that judgement belongs to whoever built the graph (a
 * domain layer might hide its framework's own plumbing subflows, a dashboard
 * might hide retries). The predicate receives the whole node, so a caller can
 * decide by id, by `data.emphasis`, by `data.isSubflow` — anything the graph
 * already carries. No id convention is special-cased here.
 *
 * Rules, stated so they can be tested (and they are — collapseTraceGraph.test):
 *
 *   1. A node the predicate matches is removed, and listed in `hiddenNodeIds`.
 *   2. A removed subflow card takes its internals with it (the nodes whose
 *      `subflowOf` scope it owns, transitively). They are NOT listed — they
 *      were only ever reachable by drilling a card that no longer exists, and
 *      counting invisible internals would overstate what the collapse hid.
 *   3. Every path THROUGH a removed node survives: predecessors connect to
 *      successors (chains of removed nodes contract fully). A contracted edge
 *      that would point a node at itself is dropped; duplicates are deduped.
 *   4. A loop edge stays a loop edge: if either contracted leg was `kind:
 *      'loop'`, the resulting edge is too — hiding a stage inside a loop must
 *      not straighten the loop.
 *   4b. A contracted edge REMEMBERS what it contracted through: `data.via`
 *      lists the removed node ids the edge now stands in for (chains
 *      accumulate; duplicate contractions union their lists). That is how a
 *      time cursor standing on a hidden node stays visible — the renderer
 *      lights the edge that carries it (`edgeCarriesCursor`) instead of
 *      going dark.
 *   5. Nothing matched → the ORIGINAL graph reference comes back (upstream
 *      memoization is preserved), with an empty `hiddenNodeIds`.
 *
 * The transform is pure and synchronous. It says what it hid; it never decides
 * what SHOULD be hidden and it never renders the sentence — absent and hidden
 * are different facts, and only the caller knows the words for them.
 */

import type { TraceGraph, TraceEdge, TraceEdgeData } from "../traceStructureRecorder";

type TraceNode = TraceGraph["nodes"][number];

export interface CollapsedTraceGraph {
  /** The graph with the hidden nodes removed and their edges contracted. The
   *  ORIGINAL reference when nothing matched. */
  readonly graph: TraceGraph;
  /**
   * The ids of the nodes the predicate matched, in graph order — what the
   * collapse HID, for the caller's honest sentence ("N steps hidden"). A
   * removed card's internals are not listed (see rule 2 above).
   */
  readonly hiddenNodeIds: readonly string[];
}

/**
 * The `subflowOf` scopes a removed mount owns, in both producer spellings
 * (mirrors `resolveDrillScope`): eui's own recorder tags internals with the
 * mount NODE id; a consumer bridge may tag them with the mount's local
 * `subflowId` instead.
 */
function scopesOf(node: TraceNode): readonly string[] {
  const local = node.data?.subflowId;
  return typeof local === "string" && local !== node.id ? [node.id, local] : [node.id];
}

export function collapseTraceGraph(
  graph: TraceGraph,
  hide: (node: TraceNode) => boolean,
): CollapsedTraceGraph {
  const hiddenNodeIds: string[] = [];
  const removed = new Set<string>();
  // The subflow scopes whose internals go with a removed card.
  const removedScopes = new Set<string>();

  for (const node of graph.nodes) {
    if (!hide(node)) continue;
    hiddenNodeIds.push(node.id);
    removed.add(node.id);
    for (const scope of scopesOf(node)) removedScopes.add(scope);
  }
  if (hiddenNodeIds.length === 0) return { graph, hiddenNodeIds };

  // Rule 2 — internals of removed cards, transitively (a nested subflow's own
  // internals follow it out). Fixed-point walk: each pass absorbs the next
  // nesting level; bounded by node count.
  let grew = true;
  while (grew) {
    grew = false;
    for (const node of graph.nodes) {
      if (removed.has(node.id)) continue;
      const parent = node.data?.subflowOf;
      if (parent !== undefined && removedScopes.has(parent)) {
        removed.add(node.id);
        for (const scope of scopesOf(node)) removedScopes.add(scope);
        grew = true;
      }
    }
  }

  // Rule 3 — contract edges through each removed node, one node at a time so
  // chains of removed nodes contract fully. Rule 4b — each contraction stamps
  // `data.via` with the node it passed through, accumulating both legs' lists
  // so a chain of removed nodes yields ONE edge that remembers all of them.
  const viaOf = (e: TraceEdge): readonly string[] =>
    Array.isArray(e.data?.via) ? (e.data.via as readonly string[]) : [];
  let edges: TraceEdge[] = [...graph.edges];
  for (const hiddenId of removed) {
    const incoming = edges.filter((e) => e.target === hiddenId && e.source !== hiddenId);
    const outgoing = edges.filter((e) => e.source === hiddenId && e.target !== hiddenId);
    edges = edges.filter((e) => e.source !== hiddenId && e.target !== hiddenId);
    for (const inEdge of incoming) {
      for (const outEdge of outgoing) {
        if (inEdge.source === outEdge.target) continue; // would be a self-loop
        // Rule 4 — a loop leg keeps the contraction a loop.
        const kind: TraceEdgeData["kind"] =
          inEdge.data?.kind === "loop" || outEdge.data?.kind === "loop"
            ? "loop"
            : (outEdge.data?.kind ?? inEdge.data?.kind ?? "next");
        const via = [...new Set([...viaOf(inEdge), hiddenId, ...viaOf(outEdge)])];
        edges.push({
          id: `${inEdge.source}->${outEdge.target}~collapsed`,
          source: inEdge.source,
          target: outEdge.target,
          data: { kind, via },
        });
      }
    }
  }

  // Dedupe: a diamond of removed nodes can contract to the same source→target
  // twice. First occurrence wins (an original edge sorts before a contraction
  // because contractions are appended) — EXCEPT `via`, which unions across the
  // duplicates: whichever copy survives must still stand in for every node any
  // copy contracted through, or a cursor on one of them would go dark.
  const byEndpoints = new Map<string, TraceEdge>();
  for (const e of edges) {
    const key = `${e.source}�${e.target}`;
    const kept = byEndpoints.get(key);
    if (kept === undefined) {
      byEndpoints.set(key, e);
      continue;
    }
    const mergedVia = [...new Set([...viaOf(kept), ...viaOf(e)])];
    if (mergedVia.length > viaOf(kept).length) {
      byEndpoints.set(key, {
        ...kept,
        data: { ...(kept.data ?? { kind: "next" as const }), via: mergedVia },
      });
    }
  }
  const dedupedEdges = [...byEndpoints.values()];

  return {
    graph: {
      nodes: graph.nodes.filter((n) => !removed.has(n.id)),
      edges: dedupedEdges,
    },
    hiddenNodeIds,
  };
}
